"""SQLite repository for high-score records."""

from dataclasses import dataclass
from datetime import datetime, timezone

from .database import Database


@dataclass(frozen=True)
class ScoreEntry:
    id: int
    player_name: str
    score: int
    total_questions: int
    played_at: str


class ScoreRepository:
    """Persists finished game scores for the high-score screen."""

    def __init__(self, db: Database):
        self.db = db

    def save(self, player_name: str, score: int, total_questions: int) -> ScoreEntry:
        played_at = datetime.now(timezone.utc).isoformat(timespec="seconds")
        with self.db.connection() as conn:
            cursor = conn.execute(
                "INSERT INTO scores (player_name, score, total_questions, played_at) VALUES (?, ?, ?, ?)",
                (player_name, score, total_questions, played_at),
            )
            new_id = cursor.lastrowid
        return ScoreEntry(id=new_id, player_name=player_name, score=score, total_questions=total_questions, played_at=played_at)

    def list_high_scores(self, limit: int = 10):
        with self.db.connection() as conn:
            rows = conn.execute(
                "SELECT id, player_name, score, total_questions, played_at FROM scores ORDER BY score DESC, played_at ASC LIMIT ?",
                (limit,),
            ).fetchall()
        return [ScoreEntry(**dict(row)) for row in rows]
